    /// <summary>
    /// The map screen's status markers, tied to the server objects whose state they show.
    ///
    /// Generated by trpython/gen_map_markers.py from the client's own
    /// generated.client.uimapmarker.factionedmarkers, matched to the teleporter and kraftwerks
    /// tables by position on the same map. 307 of the 471 markers matched, on 65 maps.
    /// Medians: crafting stations 0.00 m (they were seeded from this same marker data), hospitals
    /// 0.36 m, safe zones 1.03 m, waypoints 1.54 m. Nothing past 25 m was claimed, and the
    /// nearest thing rejected was 26 m away, so the cut sits in open water.
    ///
    /// What is not here: the 60 control points, which have no server object until 7.4; 58
    /// waypoints and hospitals on maps whose teleporter rows are the zero-coordinate
    /// placeholders; and 13 markers the client itself skips for having no type or name.
    /// A marker with no row is simply sent no state, which is what every marker gets today.
    /// </summary>
    public class MapMarkerPreloader : PreloaderBase, IPreloader
    {
        public void Preload(MigrationBuilder migrationBuilder)
        {
            Insert(migrationBuilder, MapMarkerEntry.TableName, typeof(MapMarkerEntry));
        }

